import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// The canary binding lives in the TRACKED declaration, on the local/claudinite
// pack entry's `config.canaryRepo` — the same pack-entry config mechanism the
// claudinite-fleet-sheepdog pack uses for its fleet scope.
//
// It is deliberately NOT a GitHub repository variable. A variable is invisible in
// the tree, absent from every diff, and cannot be reviewed beside the workflow
// that acts on it — and this particular value names a repo that CI will check out
// and rewrite. A reader of this repo should be able to see which one.
//
// These two facts have to stay in step: the declaration must name a canary, and
// the workflow must read it from there. Nothing else couples them, so without this
// guard the workflow could drift back to a variable (or to a hardcoded name) and
// the declared value would sit there looking authoritative while meaning nothing.
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..', '..');
const WORKFLOW = '.github/workflows/canary-rehearsal.yml';

const declaration = () => JSON.parse(readFileSync(join(ROOT, '.claudinite-settings.json'), 'utf8'));
const workflow = () => readFileSync(join(ROOT, WORKFLOW), 'utf8');

test('the workflow reads the canary from the declaration, not from a repository variable', () => {
  const text = workflow();
  assert.match(text, /\.claudinite-settings\.json/, 'the workflow no longer reads the declaration');
  assert.match(text, /canaryRepo/, 'the workflow no longer reads config.canaryRepo');
  assert.doesNotMatch(text, /vars\.CLAUDINITE_CANARY_REPO/,
    'the workflow reads a repository variable again — the binding belongs in the tracked declaration');
});

// A hardcoded name would work and be exactly as unreviewable as the variable was:
// the declaration would still look authoritative while the workflow ignored it.
test('the workflow does not hardcode the canary name', () => {
  const entry = (declaration().packs ?? []).find((p) => p && p.id === 'local/claudinite');
  const repo = entry.config.canaryRepo;
  const body = workflow().split('\n').filter((l) => !l.trim().startsWith('#')).join('\n');
  assert.ok(!body.includes(repo), `${WORKFLOW} names ${repo} literally — it must resolve it from the declaration`);
});
======== ci-test-roots
// The drift guard on CI's test roots.
//
// `.github/workflows/ci.yml` runs the suite from a CLOSED set of folders. That is the
// right shape — it is short, it is readable, and it does not enumerate directory depth
// — but a closed set has one failure mode: a test written somewhere outside it is never
// run, and CI stays green while covering less. That is not hypothetical. The previous
// form listed one glob per level of nesting, and `vendoring/` appeared in none of them,
// so both of its test files went unrun for as long as they existed — a silent 38-test
// hole nothing reported.
//
// So the root list is declared in ONE place (ci.yml, where CI actually reads it) and
// this test holds it honest: every tracked `*.test.mjs` must fall under a declared root,
// and every declared root must exist. Neither half is optional — the first catches a
// test that escapes the set, the second catches a root left behind after a rename.
//
// It lives in engine-tests/ alongside the canon's other top-level-folder tests
// (migrations.test.mjs): the roots span the whole repo, so no
// pack owns them.

import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = fileURLToPath(new URL('..', import.meta.url));
const CI = join(REPO, '.github/workflows/ci.yml');

// The one line CI runs. Parsed rather than duplicated: a second copy of the root list
// here would be the very drift this test exists to prevent.
function declaredRoots() {
  const line = readFileSync(CI, 'utf8').split('\n').find((l) => l.trim().startsWith('tests=('));
  assert.ok(line, 'ci.yml no longer has a `tests=(...)` array — this guard has lost its subject');
  const inner = line.slice(line.indexOf('(') + 1, line.lastIndexOf(')'));
  return inner.split(/\s+/).filter(Boolean).map((g) => {
    const at = g.indexOf('/**/');
    assert.notEqual(at, -1, `test glob ${g} is not a \`<root>/**/…\` sweep — depth must not be enumerated`);
    return g.slice(0, at);
  });
}

const trackedTests = () => execFileSync('git', ['ls-files', '*.test.mjs'], { cwd: REPO, encoding: 'utf8' })
  .split('\n').filter(Boolean);

test('every tracked test file falls under a root ci.yml sweeps', () => {
  const roots = declaredRoots();
  const orphans = trackedTests().filter((f) => !roots.some((r) => f.startsWith(`${r}/`)));
  assert.deepEqual(orphans, [], `these tests are tracked but CI never runs them — move them under a declared root, `
    + `or add the root to ci.yml's tests=(...): ${orphans.join(', ')}`);
});

test('every root ci.yml sweeps still exists', () => {
  const dead = declaredRoots().filter((r) => !existsSync(join(REPO, r)));
  assert.deepEqual(dead, [], `ci.yml sweeps roots that are not in the tree (renamed or deleted): ${dead.join(', ')}`);
});

