for (const f of files) {
  const src = readFileSync(f,'utf8');
  const declared = new Set([...src.matchAll(/const\s+([A-Za-z_$][\w$]*)\s*=\s*declaredCheck\(/g)].map(m=>m[1]));
  if (!declared.size) continue;
  const lines = src.split('\n');
  const drop = [];
  for (let i=0;i<lines.length;i++){
    if (!/assert\.\w+\(\s*[\w$]+(\[\d+\])?\.severity\s*,\s*'(blocking|advisory)'\s*\)/.test(lines[i])) continue;
    // nearest preceding run(...) call in the same test block
    let checkVar = null, contrast = false;
    for (let j=i-1;j>=0 && j>i-25;j--){
      const m = /\brun\(\s*([A-Za-z_$][\w$]*)\s*[,)]/.exec(lines[j]);
      if (m) { checkVar = m[1]; break; }
      if (/^\s*test\(/.test(lines[j])) break;
    }
    // a block asserting TWO different severities is a contrast -> behaviour, keep both
    let s=i, e=i;
    while (s>0 && !/^\s*test\(/.test(lines[s])) s--;
    while (e<lines.length-1 && !/^\}\);\s*$/.test(lines[e])) e++;
    const block = lines.slice(s,e+1).join('\n');
    const sevs = new Set([...block.matchAll(/\.severity\s*,\s*'(blocking|advisory)'/g)].map(m=>m[1]));
    contrast = sevs.size > 1;
    if (checkVar && declared.has(checkVar) && !contrast) drop.push(i);
  }
  if (!drop.length) continue;
  console.log(`${f}: dropping ${drop.length}`);
  for (const i of drop) console.log(`   ${i+1}: ${lines[i].trim()}`);
  if (apply) writeFileSync(f, lines.filter((_,i)=>!drop.includes(i)).join('\n'));
}
EOF
